INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('grid-escape', 8, NULL, 'def gen():
    _s = [1818974258]
    def _n():
        _s[0] = (_s[0] * 1103515245 + 12345) % 2147483648
        return _s[0] >> 8
    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    P = 30
    R = 500
    C = 500
    g = [["#" if r(1, 100) <= P else "." for _ in range(C)] for _ in range(R)]
    sr, sc = r(0, R - 1), r(0, C - 1)
    while True:
        er, ec = r(0, R - 1), r(0, C - 1)
        if (er, ec) != (sr, sc):
            break
    g[sr][sc] = "S"
    g[er][ec] = "E"
    return f"{R} {C}\n" + "\n".join("".join(row) for row in g) + "\n"
', '372', 0);
